import"./chunk-VC46IEJQ.js";var e=(o,r,t,a,n)=>({name:o,desc:r,tour:t,source:a,...n?{spoiler:n}:{}}),s={id:"tyrosh",intro:{en:"A walled harbour city on an island at the northern end of the Stepstones, where men dye their hair and forked beards in vivid colours. Ships enter under the Bleeding Tower at the harbour mouth; an Archon chosen from the richest families rules.",zh:"\u6CF0\u6D1B\u897F\u662F\u77F3\u9636\u5217\u5C9B\u5317\u7AEF\u4E00\u5EA7\u5C9B\u4E0A\u7684\u8BBE\u9632\u6E2F\u57CE\uFF0C\u7537\u4EBA\u4EEC\u628A\u5934\u53D1\u548C\u5206\u53C9\u7684\u80E1\u987B\u67D3\u6210\u8273\u4E3D\u7684\u989C\u8272\u3002\u5165\u6E2F\u8239\u53EA\u8981\u4ECE\u6E2F\u53E3\u7684\u8840\u5854\u4E0B\u9A76\u8FC7\uFF1B\u57CE\u90A6\u7531\u4ECE\u6700\u5BCC\u6709\u5BB6\u65CF\u4E2D\u63A8\u9009\u7684\u6267\u653F\u8005\u7EDF\u6CBB\u3002"},notes:{en:"From the novels: dyed hair and forked beards, the Bleeding Tower at the harbour mouth, the Fountain of the Drunken God and the Temple of Trios (both named in A Dance with Dragons), Tyroshi sellswords. From TWOIAF and wiki summaries: high walls with inner walls of fused black dragonstone, a large fleet, an elected Archon, ornate armour. Invented here: the plan, the citadel, the arsenal, the dye works and armourers' row as places, the tower's red streaks and all house colours.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u67D3\u8272\u7684\u5934\u53D1\u4E0E\u5206\u53C9\u80E1\u987B\u3001\u6E2F\u53E3\u7684\u8840\u5854\u3001\u9189\u795E\u55B7\u6CC9\u4E0E\u4E09\u5934\u795E\u795E\u5E99\uFF08\u5747\u89C1\u4E8E\u300A\u9B54\u9F99\u7684\u72C2\u821E\u300B\uFF09\u3001\u6CF0\u6D1B\u897F\u4F63\u5175\u3002\u51FA\u81EA\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u53CA\u7EF4\u57FA\u6458\u8981\uFF1A\u9AD8\u5927\u5916\u5899\u4E0E\u7194\u878D\u9ED1\u9F99\u77F3\u780C\u6210\u7684\u5185\u5899\u3001\u5E9E\u5927\u8230\u961F\u3001\u63A8\u9009\u4EA7\u751F\u7684\u6267\u653F\u8005\u3001\u534E\u7F8E\u94E0\u7532\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u57CE\u5E02\u5E03\u5C40\u3001\u5185\u57CE\u5821\u5792\u3001\u8239\u575E\u3001\u4F5C\u4E3A\u5177\u4F53\u573A\u6240\u7684\u67D3\u574A\u4E0E\u94F8\u7532\u8857\u3001\u5854\u8EAB\u7684\u7EA2\u8272\u6591\u7EB9\uFF0C\u4EE5\u53CA\u5404\u5BB6\u623F\u5C4B\u7684\u914D\u8272\u3002"},tour:["stepstones-view","bleeding-tower","harbour","arsenal","dye-works","fountain-of-the-drunken-god","temple-of-trios","armourers-row","outer-walls","inner-walls"],sources:[{ref:"affc",checked:"memory",note:{en:"A ship sailing past the Bleeding Tower into Tyrosh on a voyage south, and Tyroshi with dyed forked beards, recalled from memory, not re-read.",zh:"\u4E00\u8258\u5357\u884C\u7684\u8239\u9A76\u8FC7\u8840\u5854\u3001\u505C\u9760\u6CF0\u6D1B\u897F\uFF0C\u4EE5\u53CA\u67D3\u7740\u5206\u53C9\u80E1\u987B\u7684\u6CF0\u6D1B\u897F\u4EBA\uFF0C\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"adwd",checked:"search-snippet",note:{en:"The Fountain of the Drunken God and the Temple of Trios, named in a performer's story: confirmed via a web-search summary of the wiki, not the text.",zh:"\u9189\u795E\u55B7\u6CC9\u4E0E\u4E09\u5934\u795E\u795E\u5E99\u51FA\u73B0\u5728\u4E00\u4F4D\u827A\u4EBA\u7684\u8BB2\u8FF0\u4E2D\uFF1A\u636E\u7EF4\u57FA\u7684\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF0C\u672A\u67E5\u9605\u539F\u6587\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Bleeding Tower at the harbour mouth; inner walls of fused black dragonstone; large fleet; Archon chosen from a conclave of the wealthiest and noblest; ornate armour: from web-search summaries (pages not fetched). Nothing found about an arsenal.",zh:"\u6E2F\u53E3\u5165\u53E3\u7684\u8840\u5854\u3001\u7194\u878D\u9ED1\u9F99\u77F3\u5185\u5899\u3001\u5E9E\u5927\u8230\u961F\u3001\u7531\u6700\u5BCC\u6709\u663E\u8D35\u8005\u7EC4\u6210\u7684\u8BAE\u4F1A\u63A8\u9009\u6267\u653F\u8005\u3001\u534E\u7F8E\u94E0\u7532\uFF1A\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\uFF08\u672A\u80FD\u6253\u5F00\u9875\u9762\uFF09\u3002\u672A\u627E\u5230\u4EFB\u4F55\u5173\u4E8E\u8239\u575E\u7684\u8BB0\u8F7D\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Position relative to the Stepstones and the Disputed Lands: search summary only.",zh:"\u76F8\u5BF9\u77F3\u9636\u5217\u5C9B\u4E0E\u4E89\u8BAE\u4E4B\u5730\u7684\u4F4D\u7F6E\uFF1A\u4EC5\u636E\u641C\u7D22\u6458\u8981\u3002"}}],landmarks:{"bleeding-tower":e({en:"Bleeding Tower",zh:"\u8840\u5854"},{en:"A tall tower at the mouth of the harbour that every arriving ship must pass.",zh:"\u77D7\u7ACB\u5728\u6E2F\u53E3\u5165\u53E3\u7684\u9AD8\u5854\uFF0C\u6BCF\u8258\u5165\u6E2F\u8239\u53EA\u90FD\u8981\u4ECE\u5B83\u811A\u4E0B\u7ECF\u8FC7\u3002"},{en:"Ships entering Tyrosh sail past the Bleeding Tower.",zh:"\u9A76\u5165\u6CF0\u6D1B\u897F\u7684\u8239\u53EA\uFF0C\u90FD\u8981\u7ECF\u8FC7\u8840\u5854\u3002"},{confidence:"medium",refs:["affc","awoiaf"],book:{en:"The tower overlooks the harbour mouth; ships pass it on their way in.",zh:"\u5854\u4FEF\u77B0\u6E2F\u53E3\u5165\u53E3\uFF0C\u8239\u53EA\u5165\u6E2F\u65F6\u4ECE\u65C1\u9A76\u8FC7\u3002"},unknown:{en:'Why it is called "Bleeding", its height and its shape.',zh:"\u201C\u8840\u5854\u201D\u4E4B\u540D\u7684\u7531\u6765\u3001\u5854\u9AD8\u4E0E\u5F62\u5236\u3002"},interpretation:{en:"A round tower with red streaks and a beacon; the streaks are this scene's reading of the name.",zh:"\u5E26\u7EA2\u8272\u6591\u7EB9\u4E0E\u70FD\u706B\u7684\u5706\u5854\uFF1B\u6591\u7EB9\u662F\u672C\u573A\u666F\u5BF9\u540D\u79F0\u7684\u6F14\u7ECE\u3002"}}),harbour:e({en:"Harbour",zh:"\u6E2F\u53E3"},{en:"A deep cove reached by a channel, crowded with the galleys of a large fleet.",zh:"\u7ECF\u822A\u9053\u9A76\u5165\u7684\u6DF1\u6E7E\uFF0C\u6CCA\u6EE1\u4E00\u652F\u5E9E\u5927\u8230\u961F\u7684\u6868\u5E06\u8239\u3002"},{en:"Tyrosh keeps a large fleet, and this is where it lies.",zh:"\u6CF0\u6D1B\u897F\u62E5\u6709\u5E9E\u5927\u7684\u8230\u961F\uFF0C\u8239\u5C31\u6CCA\u5728\u8FD9\u91CC\u3002"},{confidence:"medium",refs:["affc","twoiaf"],book:{en:"Tyrosh is a harbour city; a large fleet is attributed to it in companion summaries.",zh:"\u6CF0\u6D1B\u897F\u662F\u6E2F\u57CE\uFF1B\u8BBE\u5B9A\u96C6\u6458\u8981\u79F0\u5176\u62E5\u6709\u5E9E\u5927\u8230\u961F\u3002"},unknown:{en:"Harbour shape and capacity.",zh:"\u6E2F\u53E3\u5F62\u72B6\u4E0E\u5BB9\u91CF\u3002"},interpretation:{en:"A round cove with a narrow south-east channel.",zh:"\u5706\u5F62\u6D77\u6E7E\uFF0C\u4E1C\u5357\u65B9\u4E00\u6761\u7A84\u822A\u9053\u3002"}}),"fountain-of-the-drunken-god":e({en:"Drunken God Fountain",zh:"\u9189\u795E\u55B7\u6CC9"},{en:"A tiled square with a fountain basin and a cheerful statue.",zh:"\u94FA\u7816\u5E7F\u573A\u4E2D\u7684\u55B7\u6CC9\u6C34\u6C60\uFF0C\u7ACB\u7740\u4E00\u5C0A\u61A8\u6001\u53EF\u63AC\u7684\u96D5\u50CF\u3002"},{en:"Street performers once drew crowds beside this fountain.",zh:"\u8857\u5934\u827A\u4EBA\u66FE\u5728\u8FD9\u5EA7\u55B7\u6CC9\u8FB9\u62DB\u5F95\u89C2\u4F17\u3002"},{confidence:"medium",refs:["adwd","awoiaf"],book:{en:"A fountain of this name stands in a square in Tyrosh; a juggler is said to have performed beside it.",zh:"\u6CF0\u6D1B\u897F\u67D0\u5904\u5E7F\u573A\u4E0A\u6709\u4E00\u5EA7\u540C\u540D\u55B7\u6CC9\uFF1B\u4E66\u4E2D\u63D0\u5230\u4E00\u540D\u6742\u800D\u827A\u4EBA\u66FE\u5728\u65C1\u8868\u6F14\u3002"},unknown:{en:"The fountain's look and where the square lies.",zh:"\u55B7\u6CC9\u7684\u6837\u5B50\u4E0E\u5E7F\u573A\u4F4D\u7F6E\u3002"},interpretation:{en:"A chequer-tiled square with a gilded figure holding a cup.",zh:"\u65B9\u683C\u94FA\u5730\u7684\u5E7F\u573A\uFF0C\u4E2D\u592E\u7ACB\u7740\u4E00\u5C0A\u4E3E\u676F\u7684\u9540\u91D1\u4EBA\u50CF\u3002"}}),"temple-of-trios":e({en:"Temple of Trios",zh:"\u4E09\u5934\u795E\u795E\u5E99"},{en:"A temple of Trios, the three-headed god, shown with three towers.",zh:"\u4F9B\u5949\u4E09\u5934\u795E\u7684\u795E\u5E99\uFF0C\u4EE5\u4E09\u5EA7\u5854\u697C\u793A\u610F\u3002"},{en:"Three towers for a god with three heads.",zh:"\u4E09\u5934\u4E4B\u795E\uFF0C\u4E09\u5EA7\u9AD8\u5854\u3002"},{confidence:"medium",refs:["adwd","twoiaf"],book:{en:"The Temple of Trios is named in the novels; Trios is recalled as a three-headed god worshipped in Tyrosh.",zh:"\u4E09\u5934\u795E\u795E\u5E99\u89C1\u4E8E\u5C0F\u8BF4\uFF1B\u636E\u8BB0\u5FC6\uFF0C\u4E09\u5934\u795E\u662F\u6CF0\u6D1B\u897F\u4EBA\u4FE1\u5949\u7684\u4E00\u4F4D\u4E09\u9996\u795E\u7947\u3002"},unknown:{en:"Its architecture.",zh:"\u5EFA\u7B51\u6837\u5F0F\u3002"},interpretation:{en:"Three towers in three colours behind a triple-roofed hall.",zh:"\u4E09\u91CD\u5C4B\u9876\u7684\u6BBF\u5802\u540E\u7ACB\u7740\u4E09\u8272\u4E09\u5854\u3002"}}),"inner-walls":e({en:"Black Inner Walls",zh:"\u9ED1\u8272\u5185\u5899"},{en:"Inner walls of fused black dragonstone enclose a citadel on the hill.",zh:"\u7194\u878D\u9ED1\u9F99\u77F3\u780C\u6210\u7684\u5185\u5899\uFF0C\u73AF\u7ED5\u7740\u5C71\u4E18\u4E0A\u7684\u5185\u57CE\u5821\u5792\u3002"},{en:"Black and seamless: walls fused in the Valyrian manner.",zh:"\u6F06\u9ED1\u65E0\u7F1D\uFF1A\u4EE5\u74E6\u96F7\u5229\u4E9A\u4E4B\u6CD5\u7194\u94F8\u7684\u57CE\u5899\u3002"},{confidence:"medium",refs:["twoiaf","awoiaf"],book:{en:"Companion summaries describe inner walls of fused black dragonstone.",zh:"\u8BBE\u5B9A\u96C6\u6458\u8981\u79F0\u5176\u5185\u5899\u7531\u7194\u878D\u7684\u9ED1\u9F99\u77F3\u7B51\u6210\u3002"},unknown:{en:"Extent, height and what lies inside.",zh:"\u8303\u56F4\u3001\u9AD8\u5EA6\u4E0E\u5899\u5185\u60C5\u5F62\u3002"},interpretation:{en:"A glossy black ring wall with towers around a black keep; the citadel is invented.",zh:"\u5E26\u5854\u697C\u7684\u5149\u4EAE\u9ED1\u8272\u73AF\u5899\uFF0C\u56F4\u7740\u4E00\u5EA7\u9ED1\u8272\u4E3B\u5821\uFF1B\u5185\u57CE\u5821\u5792\u7CFB\u81EA\u62DF\u3002"}}),"outer-walls":e({en:"Outer Walls",zh:"\u5916\u5899"},{en:"High pale walls with square towers and a gate on the landward side.",zh:"\u9646\u4FA7\u9AD8\u5927\u7684\u6D45\u8272\u57CE\u5899\uFF0C\u8BBE\u65B9\u5854\u4E0E\u57CE\u95E8\u3002"},{en:"A fortress city: high walls on the land side, the sea on the other.",zh:"\u4E00\u5EA7\u8981\u585E\u57CE\u5E02\uFF1A\u4E00\u9762\u662F\u9AD8\u5899\uFF0C\u4E00\u9762\u662F\u5927\u6D77\u3002"},{confidence:"medium",refs:["twoiaf","awoiaf"],book:{en:"Tyrosh is a fortress city protected by high walls (companion summaries).",zh:"\u6CF0\u6D1B\u897F\u662F\u7531\u9AD8\u5899\u5B88\u62A4\u7684\u8981\u585E\u57CE\u5E02\uFF08\u636E\u8BBE\u5B9A\u96C6\u6458\u8981\uFF09\u3002"},unknown:{en:"Layout.",zh:"\u5E03\u5C40\u3002"},interpretation:{en:"A wall arc with square towers and one gatehouse.",zh:"\u4E00\u9053\u5E26\u65B9\u5854\u4E0E\u95E8\u697C\u7684\u5F27\u5F62\u57CE\u5899\u3002"}}),"dye-works":e({en:"Dye Works",zh:"\u67D3\u574A"},{en:"Vats of every colour, with cloth hung out to dry beside the shore.",zh:"\u6D77\u8FB9\u4E00\u6392\u6392\u4E94\u989C\u516D\u8272\u7684\u67D3\u7F38\uFF0C\u5E03\u5339\u667E\u5728\u4E00\u65C1\u3002"},{en:"Tyroshi love vivid dyes; here the colours are imagined being made.",zh:"\u6CF0\u6D1B\u897F\u4EBA\u504F\u7231\u8273\u4E3D\u7684\u67D3\u8272\uFF1B\u8BBE\u60F3\u8272\u5F69\u5C31\u5728\u8FD9\u91CC\u8C03\u51FA\u3002"},{confidence:"low",refs:["affc","adwd"],book:{en:"Tyroshi dye their hair and beards in bright colours; a dyeing district is an extrapolation.",zh:"\u6CF0\u6D1B\u897F\u4EBA\u628A\u5934\u53D1\u4E0E\u80E1\u987B\u67D3\u6210\u9C9C\u8273\u7684\u989C\u8272\uFF1B\u67D3\u574A\u533A\u5219\u662F\u63A8\u6F14\u3002"},unknown:{en:"Whether Tyrosh is a dye-making centre in the books.",zh:"\u4E66\u4E2D\u6CF0\u6D1B\u897F\u662F\u5426\u662F\u67D3\u6599\u4EA7\u5730\u3002"},interpretation:{en:"A paved yard of coloured vats with cloth racks.",zh:"\u94FA\u77F3\u9662\u843D\u91CC\u6446\u6EE1\u5F69\u8272\u67D3\u7F38\u4E0E\u667E\u5E03\u67B6\u3002"}}),"armourers-row":e({en:"Armourers' Row",zh:"\u94F8\u7532\u8857"},{en:"Forges where craftsmen make ornate helms and armour.",zh:"\u5320\u4EBA\u6253\u9020\u534E\u7F8E\u5934\u76D4\u4E0E\u94E0\u7532\u7684\u4E00\u6761\u4F5C\u574A\u8857\u3002"},{en:"Tyroshi craftsmen are known for ornate armour.",zh:"\u6CF0\u6D1B\u897F\u5320\u4EBA\u4EE5\u534E\u7F8E\u7684\u94E0\u7532\u8457\u79F0\u3002"},{confidence:"low",refs:["awoiaf"],book:{en:"A search summary mentions Tyroshi craftsmen making ornate helms and armour.",zh:"\u641C\u7D22\u6458\u8981\u63D0\u5230\u6CF0\u6D1B\u897F\u5320\u4EBA\u5236\u4F5C\u534E\u7F8E\u7684\u5934\u76D4\u4E0E\u94E0\u7532\u3002"},unknown:{en:"Where they work.",zh:"\u4F5C\u574A\u6240\u5728\u3002"},interpretation:{en:"Four smithies with display helms on the north-west slope.",zh:"\u897F\u5317\u5761\u4E0A\u56DB\u95F4\u9648\u5217\u5934\u76D4\u7684\u94C1\u5320\u94FA\u3002"}}),arsenal:e({en:"Arsenal",zh:"\u8239\u575E"},{en:"Long galley sheds under bright roofs on the southern shore.",zh:"\u5357\u5CB8\u4E00\u6392\u5F69\u8272\u5C4B\u9876\u7684\u957F\u5F62\u8239\u68DA\u3002"},{en:"A big fleet needs a big yard.",zh:"\u8230\u961F\u5E9E\u5927\uFF0C\u8239\u575E\u81EA\u7136\u4E5F\u5C0F\u4E0D\u4E86\u3002"},{confidence:"low",refs:["twoiaf"],book:{en:"A large fleet is attributed to Tyrosh; no arsenal is described in the sources checked.",zh:"\u6CF0\u6D1B\u897F\u88AB\u8BA4\u4E3A\u62E5\u6709\u5E9E\u5927\u8230\u961F\uFF1B\u6240\u67E5\u8D44\u6599\u672A\u63D0\u53CA\u8239\u575E\u3002"},unknown:{en:"Whether it exists, and where.",zh:"\u662F\u5426\u5B58\u5728\uFF0C\u4F4D\u4E8E\u4F55\u5904\u3002"},interpretation:{en:"Six coloured sheds and a watchtower; invented.",zh:"\u516D\u5EA7\u5F69\u8272\u8239\u68DA\u4E0E\u4E00\u5EA7\u77AD\u671B\u5854\uFF1B\u7CFB\u81EA\u62DF\u3002"}}),"stepstones-view":e({en:"Stepstones Route",zh:"\u77F3\u9636\u5217\u5C9B\u822A\u7EBF"},{en:"Bare rocky islets offshore stand in for the Stepstones, the pirate-haunted chain between Tyrosh and Dorne.",zh:"\u8FD1\u6D77\u51E0\u5EA7\u5149\u79C3\u7684\u7901\u5C9B\uFF0C\u4EE3\u8868\u77F3\u9636\u5217\u5C9B\u2014\u2014\u6A2A\u4E98\u5728\u6CF0\u6D1B\u897F\u4E0E\u591A\u6069\u4E4B\u95F4\u3001\u6D77\u76D7\u51FA\u6CA1\u7684\u5C9B\u94FE\u3002"},{en:"Beyond lie the Stepstones, stepping toward Dorne.",zh:"\u8FDC\u5904\u4FBF\u662F\u77F3\u9636\u5217\u5C9B\uFF0C\u4E00\u8DEF\u5EF6\u4F38\u5411\u591A\u6069\u3002"},{confidence:"medium",refs:["maps","twoiaf"],book:{en:"Tyrosh lies at the northern end of the Stepstones, the island chain between Essos and Dorne.",zh:"\u6CF0\u6D1B\u897F\u4F4D\u4E8E\u77F3\u9636\u5217\u5C9B\u5317\u7AEF\uFF0C\u8FD9\u6761\u5C9B\u94FE\u8FDE\u63A5\u5384\u7D22\u65AF\u4E0E\u591A\u6069\u4E4B\u95F4\u7684\u6D77\u57DF\u3002"},unknown:{en:"Exact distances and the shapes of the islets.",zh:"\u786E\u5207\u8DDD\u79BB\u4E0E\u5404\u7901\u5C9B\u5F62\u72B6\u3002"},interpretation:{en:"A few rocks placed off the island for atmosphere; on the maps the chain runs south-west toward Dorne.",zh:"\u5C9B\u5916\u968F\u610F\u6446\u653E\u51E0\u5757\u7901\u77F3\u8425\u9020\u6C14\u6C1B\uFF1B\u5730\u56FE\u4E0A\u7684\u5C9B\u94FE\u5176\u5B9E\u5411\u897F\u5357\u5EF6\u4F38\u81F3\u591A\u6069\u3002"}})}};export{s as default};
